from fastapi import FastAPI, APIRouter
import pytest

def test_include_router_in_itself():
    router = APIRouter()
    try:
        router.include_router(router)
        print("Failed to raise error")
    except Exception as e:
        print(f"Raised: {type(e).__name__}: {e}")

def test_app_include_router_in_itself():
    app = FastAPI()
    try:
        app.include_router(app)
        print("Failed to raise error for app.include_router(app)")
    except Exception as e:
        print(f"Raised: {type(e).__name__}: {e}")

if __name__ == "__main__":
    test_include_router_in_itself()
    test_app_include_router_in_itself()
EOF
